mapper.select:
SELECT *, name AS departmentName, (SELECT DATE_ADD(#{filter.date}, INTERVAL -1 MONTH)) AS datePreviousMonth FROM departments WHERE is_active = 1 AND id IN (SELECT department_id FROM employees WHERE is_active = 1)
AND group_id = #{filter.groupId} AND user_apply = 0
AND id = #{filter.departmentId}

SELECT
    COALESCE(SUM(total_amount),0)
FROM payrolls
WHERE is_active = 1 AND employee_id IN (SELECT id FROM employees WHERE is_active = 1 AND department_id = #{departmentId}
AND MONTH(pay_date) = MONTH(#{date}) AND YEAR(pay_date) = YEAR(#{date}))
AND (
  employee_id IN (
    SELECT employee_id FROM employee_apply_status AS eas WHERE eas.is_active = 1 AND eas.employee_status_id NOT IN(4,5,6)
  ) OR employee_id IN (
    SELECT employee_id FROM employee_apply_status AS eas WHERE eas.is_active = 1
       AND eas.employee_status_id IN (4,5,6)
       AND MONTH(eas.date) > MONTH(#{date}) AND YEAR(eas.date) >= YEAR(#{date})
  ) OR employee_id IN (
    SELECT employee_id FROM payrolls WHERE is_active = 1 AND employee_id = employee_id AND MONTH(pay_date) = MONTH(#{date}) AND YEAR(pay_date) = YEAR(#{date})
  )
)
